using System;using System.Drawing;using System.Windows.Forms;
static class UiDialogs {
 public static TableLayoutPanel Layout(int rows){return new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(20),Margin=new Padding(0),ColumnCount=1,RowCount=rows};}
 public static FlowLayoutPanel Buttons(string cancel, string accept, out Button ok, out Button back){var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,WrapContents=false,Margin=new Padding(0),Padding=new Padding(0,8,0,0)};ok=new StyledButton{Text=accept,DialogResult=DialogResult.OK,Width=130,Height=36,Margin=new Padding(8,0,0,0),Primary=true};back=new StyledButton{Text=cancel,DialogResult=DialogResult.Cancel,Width=110,Height=36,Margin=new Padding(8,0,0,0)};bar.Controls.Add(ok);bar.Controls.Add(back);return bar;}
 public static void Error(Form owner,string text,string title,string close){using(var d=new ThemedForm{Text=title,ClientSize=new Size(660,380),Font=owner.Font,BackColor=UiTheme.Background,ForeColor=UiTheme.Text,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var layout=Layout(2);layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,52));var body=new TextBox{Text=text,ReadOnly=true,Multiline=true,Dock=DockStyle.Fill,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None,BackColor=Color.White,ForeColor=UiTheme.Text};layout.Controls.Add(UiTheme.Card(body),0,0);Button ok,back;var buttons=Buttons(close,close,out ok,out back);back.Visible=false;layout.Controls.Add(buttons,0,1);d.AcceptButton=ok;d.CancelButton=ok;d.Controls.Add(layout);d.ShowDialog(owner);}}
}
